solution.solution.js:
function escapeHtml(text) {
  return String(text)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

function renderItems(items) {
  if (items.length === 0) return '<p class="empty">Nothing to buy.</p>';
  const rows = items.map((item, i) => {
    const cls = item.done ? ' class="done"' : "";
    const qty = item.qty > 1 ? ` <span class="qty">×${item.qty}</span>` : "";
    return `<li data-index="${i}"${cls}>${escapeHtml(item.name)}${qty}</li>`;
  });
  return `<ul class="items">${rows.join("")}</ul>`;
}

function highlight(text, query) {
  if (!query) return escapeHtml(text);
  const lower = text.toLowerCase();
  const q = query.toLowerCase();
  let out = "";
  let i = 0;
  while (true) {
    const at = lower.indexOf(q, i);
    if (at === -1) break;
    out += escapeHtml(text.slice(i, at)) + "<mark>" + escapeHtml(text.slice(at, at + q.length)) + "</mark>";
    i = at + q.length;
  }
  return out + escapeHtml(text.slice(i));
}

unitTests:
test("escaping", () => {
  checkEq(escapeHtml(`<a href="x">Tom & Jerry's</a>`), "&lt;a href=&quot;x&quot;&gt;Tom &amp; Jerry&#39;s&lt;/a&gt;");
  checkEq(escapeHtml("&lt;"), "&amp;lt;");
  checkEq(escapeHtml(42), "42");
});

test("rendering a list", () => {
  checkEq(renderItems([{ name: "Milk", qty: 2, done: false }, { name: "Eggs & ham", qty: 1, done: true }]),
    '<ul class="items"><li data-index="0">Milk <span class="qty">×2</span></li><li data-index="1" class="done">Eggs &amp; ham</li></ul>');
  checkEq(renderItems([]), '<p class="empty">Nothing to buy.</p>');
});

test("no injection through names", () => {
  const html = renderItems([{ name: '<img src=x onerror="alert(1)">', qty: 1, done: false }]);
  check(!html.includes("<img"), "the name must be escaped");
  checkEq(html, '<ul class="items"><li data-index="0">&lt;img src=x onerror=&quot;alert(1)&quot;&gt;</li></ul>');
});

test("highlighting matches", () => {
  checkEq(highlight("Tea <b> tea", "tea"), "<mark>Tea</mark> &lt;b&gt; <mark>tea</mark>");
  checkEq(highlight("banana", "an"), "b<mark>an</mark><mark>an</mark>a");
  checkEq(highlight("a<b", ""), "a&lt;b");
  checkEq(highlight("x & y", "&"), "x <mark>&amp;</mark> y");
  checkEq(highlight("none", "zz"), "none");
});

